<?php
declare(strict_types=1);
namespace CetechDeliveryEngine\Tests\Unit\CustomerPolicy;
use CetechDeliveryEngine\Application\CustomerPolicy\CustomerPolicyFinalGuard;
use CetechDeliveryEngine\Application\EmergencyControl\{EmergencyCheckoutLocalBinding,EmergencyFinalPlacementGuard,EmergencyOrderQuoteValidatorInterface};
use PHPUnit\Framework\TestCase;
final class CustomerPolicyFinalGuardTest extends TestCase {
 public function test_unowned_orders_keep_exact_old_fingerprint_and_delegate_results():void {$a=new PolicyFinalSpy();$b=new PolicyFinalSpy();$b->throw=true;$g=new CustomerPolicyFinalGuard($a,$a,$b,$b,fn()=>false,fn()=>throw new \RuntimeException());$o=new \WC_Order();self::assertSame($a->digest,$g->fingerprint($o));self::assertTrue($g->validate_order($o,'classic'));self::assertTrue($g->complete($o,'classic',7,self::binding()));self::assertTrue($g->admitted($o,'classic',7,self::binding()));self::assertSame([],$b->calls);}
 public function test_owned_history_binds_policy_bytes_and_each_final_guard():void {$a=new PolicyFinalSpy();$b=new PolicyFinalSpy();$b->digest=str_repeat('b',64);$g=new CustomerPolicyFinalGuard($a,$a,$b,$b,fn()=>true,fn()=>false);$o=new \WC_Order();$expected=hash('sha256','cetech-policy-final-composite-v1:'.$a->digest.':'.$b->digest);self::assertSame($expected,$g->fingerprint($o));self::assertTrue($g->validate_order($o,'classic'));self::assertTrue($g->complete($o,'classic',7,self::binding()));self::assertTrue($g->admitted($o,'classic',7,self::binding()));self::assertSame(['validate','complete','admitted'],$b->calls);$b->digest=str_repeat('c',64);self::assertNotSame($expected,$g->fingerprint($o));}
 public function test_overlapping_or_unknown_owner_never_gets_legacy_fallback():void {foreach([true,null,0]as$owner){$a=new PolicyFinalSpy();$b=new PolicyFinalSpy();$g=new CustomerPolicyFinalGuard($a,$a,$b,$b,fn()=>true,fn()=>$owner);$o=new \WC_Order();self::assertNull($g->fingerprint($o));self::assertFalse($g->validate_order($o,'classic'));self::assertFalse($g->complete($o,'classic',1,self::binding()));self::assertFalse($g->admitted($o,'classic',1,self::binding()));self::assertSame([],$b->calls);}}
 public function test_late_first_policy_marker_inside_ordinary_delegate_refuses_all_four_paths():void {foreach(['fingerprint','validate_order','complete','admitted']as$method){$owned=false;$a=new PolicyFinalSpy();$b=new PolicyFinalSpy();$a->effect=static function()use(&$owned):void{$owned=true;};$g=new CustomerPolicyFinalGuard($a,$a,$b,$b,static function()use(&$owned):bool{return$owned;},fn()=>false);$r=self::call($g,$method);self::assertTrue($owned);self::assertSame('fingerprint'===$method?null:false,$r);self::assertSame([],$b->calls);}}
 public function test_late_foreign_owner_inside_policy_delegate_refuses_all_four_paths():void {foreach(['fingerprint','validate_order','complete','admitted']as$method){$other=false;$a=new PolicyFinalSpy();$b=new PolicyFinalSpy();$b->effect=static function()use(&$other):void{$other=true;};$g=new CustomerPolicyFinalGuard($a,$a,$b,$b,fn()=>true,static function()use(&$other):bool{return$other;});self::assertSame('fingerprint'===$method?null:false,self::call($g,$method));self::assertTrue($other);}}
 public function test_bound_retry_and_saved_payment_do_not_load_current_products():void {foreach(['classic','store_api','order_pay']as$route){$a=new PolicyFinalSpy();$a->throw=true;$b=new PolicyFinalSpy();$g=new CustomerPolicyFinalGuard($a,$a,$b,$b,fn()=>true,fn()=>false,fn()=>false);self::assertTrue($g->validate_order(new \WC_Order(),$route));self::assertSame([],$a->calls);self::assertSame(['validate'],$b->calls);}}
 public function test_new_capture_still_checks_basic_price_and_unknown_mode_refuses():void {foreach([true,null,'false',0]as$mode){$a=new PolicyFinalSpy();$a->allow=false;$b=new PolicyFinalSpy();$g=new CustomerPolicyFinalGuard($a,$a,$b,$b,fn()=>true,fn()=>false,fn()=>$mode);self::assertFalse($g->validate_order(new \WC_Order(),'classic'));self::assertSame([],$b->calls);}}
 public function test_either_final_collaborator_failure_refuses():void {foreach(['legacy','policy']as$side){$a=new PolicyFinalSpy();$b=new PolicyFinalSpy();if('legacy'===$side){$a->allow=false;}else{$b->allow=false;}$g=new CustomerPolicyFinalGuard($a,$a,$b,$b,fn()=>true,fn()=>false);self::assertFalse($g->validate_order(new \WC_Order(),'classic'));self::assertFalse($g->complete(new \WC_Order(),'classic',1,self::binding()));self::assertFalse($g->admitted(new \WC_Order(),'classic',1,self::binding()));}}
 private static function call(CustomerPolicyFinalGuard$g,string$m):mixed {$o=new \WC_Order();return match($m){'fingerprint'=>$g->fingerprint($o),'validate_order'=>$g->validate_order($o,'classic'),default=>$g->$m($o,'classic',1,self::binding())};}
 private static function binding():EmergencyCheckoutLocalBinding{return(new \ReflectionClass(EmergencyCheckoutLocalBinding::class))->newInstanceWithoutConstructor();}
}
final class PolicyFinalSpy implements EmergencyFinalPlacementGuard,EmergencyOrderQuoteValidatorInterface {
 public string$digest;public bool$allow=true;public bool$throw=false;public array$calls=[];public ?\Closure$effect=null;
 public function __construct(){$this->digest=str_repeat('a',64);}private function enter():void{if(null!==$this->effect){($this->effect)();}if($this->throw){throw new \RuntimeException();}}
 public function fingerprint(\WC_Order$o):?string{$this->enter();return$this->digest;}
 public function validate_order(\WC_Order$o,string$r):bool{$this->enter();$this->calls[]='validate';return$this->allow;}
 public function complete(\WC_Order$o,string$r,int$v,EmergencyCheckoutLocalBinding$b):bool{$this->enter();$this->calls[]='complete';return$this->allow;}
 public function admitted(\WC_Order$o,string$r,int$v,EmergencyCheckoutLocalBinding$b):bool{$this->enter();$this->calls[]='admitted';return$this->allow;}
}
